CARDIO.register({"item":"p110","meta":{"num":"p110","label":"110","spe":"pneumo","short":"Troubles du sommeil","title":"Troubles du sommeil de l'enfant et de l'adulte","section":"P","chapter":2,"pages":"17-28","sdd":[]},"objectives":[{"id":"p110-obj-01","rank":"A","rubric":"Contenu multimédia","title":"Photographies d'un exemple typique d'hypertrophie amygdalienne obstructive","desc":""},{"id":"p110-obj-02","rank":"A","rubric":"Définition","title":"Connaître l'architecture du sommeil normal de l'adulte et le rythme veille-sommeil","desc":""},{"id":"p110-obj-03","rank":"A","rubric":"Définition","title":"Connaître la définition du sommeil normal et les spécificités pédiatriques","desc":""},{"id":"p110-obj-04","rank":"A","rubric":"Définition","title":"Identifier et définir un trouble du sommeil chez l'enfant et chez l'adulte","desc":""},{"id":"p110-obj-05","rank":"A","rubric":"Définition","title":"Connaître la définition d'un syndrome d'apnée du sommeil (SAS)","desc":""},{"id":"p110-obj-06","rank":"B","rubric":"Diagnostic positif","title":"Savoir évaluer une hypersomnolence","desc":""},{"id":"p110-obj-07","rank":"B","rubric":"Diagnostic positif","title":"Connaître les signes cliniques du syndrome des jambes sans repos et des mouvements périodiques du sommeil","desc":""},{"id":"p110-obj-08","rank":"B","rubric":"Diagnostic positif","title":"Connaître le principal diagnostic différentiel de l'insomnie chronique","desc":""},{"id":"p110-obj-09","rank":"A","rubric":"Diagnostic positif","title":"Connaître les signes cliniques évocateurs de syndrome d'apnées hypopnées obstructives du sommeil (SAHOS) de l'adulte","desc":""},{"id":"p110-obj-10","rank":"A","rubric":"Diagnostic positif","title":"Connaître les signes cliniques révélant une hypertrophie obstructive des végétations adénoïdes de l'enfant","desc":""},{"id":"p110-obj-11","rank":"A","rubric":"Diagnostic positif","title":"Connaître les signes cliniques révélant une hypertrophie amygdalienne obstructive de l'enfant","desc":""},{"id":"p110-obj-12","rank":"B","rubric":"Étiologies","title":"Connaître les signes évocateurs d'un syndrome d'apnées obstructives du sommeil de l'enfant","desc":""},{"id":"p110-obj-13","rank":"A","rubric":"Étiologies","title":"Connaître les principales étiologies de troubles du sommeil","desc":""},{"id":"p110-obj-14","rank":"A","rubric":"Étiologies","title":"Connaître les facteurs de risque de SAS et les comorbidités / complications associées","desc":""},{"id":"p110-obj-15","rank":"A","rubric":"Examens complémentaires","title":"Connaître le bilan et la conduite à tenir devant une insomnie","desc":""},{"id":"p110-obj-16","rank":"B","rubric":"Examens complémentaires","title":"Connaître les modalités d'évaluation du SAS","desc":""},{"id":"p110-obj-17","rank":"B","rubric":"Épidémiologie","title":"Connaître l'importance du SAS sur le plan épidémiologique","desc":""},{"id":"p110-obj-18","rank":"B","rubric":"Prise en charge","title":"Connaître les principes de la prise en charge des troubles du sommeil chez l'adulte et l'enfant","desc":""},{"id":"p110-obj-19","rank":"A","rubric":"Définition","title":"Connaître les conseils d'hygiène du sommeil","desc":""},{"id":"p110-obj-20","rank":"A","rubric":"Prise en charge","title":"Connaître la prévention des troubles du sommeil chez l'adulte et l'enfant","desc":""},{"id":"p110-obj-21","rank":"A","rubric":"Prise en charge","title":"Connaître les principales règles d'hygiène pour lutter contre l'insomnie","desc":""},{"id":"p110-obj-22","rank":"B","rubric":"Prise en charge","title":"Connaître les conséquences du SAS dans l'activité professionnelle et leurs implications pour la vie professionnelle","desc":""},{"id":"p110-obj-23","rank":"B","rubric":"Prise en charge","title":"Connaître les principes du traitement du SAS","desc":""}],"course":{"sections":[],"essentials":[],"numbers":[],"mnemonics":[]},"questions":[{"id":"p110-qroc-001","type":"QROC","rank":"A","objective":"p110-obj-02","tags":["définition"],"difficulty":1,"question":"Quels sont les trois stades du sommeil ?","answer":"Léger, profond et paradoxal","accept":["léger profond paradoxal","léger, profond, paradoxal","sommeil léger, profond et paradoxal","sommeil léger sommeil profond sommeil paradoxal"],"keywords":["léger","profond","paradoxal"],"explanation":"Ces trois stades alternent pour former un cycle de sommeil ; on compte 4 à 6 cycles au cours d'un sommeil normal.","src":"p. 19"},{"id":"p110-qroc-002","type":"QROC","rank":"A","objective":"p110-obj-02","tags":["définition"],"difficulty":1,"question":"Quelle est la durée habituelle d'un cycle de sommeil ?","answer":"90 à 110 minutes","accept":["90 à 110 min","90-110 minutes","entre 90 et 110 minutes","90 à 110"],"keywords":["90","110"],"explanation":"Un cycle (stades léger, profond, paradoxal) dure en général 90 à 110 minutes ; un sommeil normal comporte 4 à 6 cycles.","src":"p. 19"},{"id":"p110-qroc-003","type":"QROC","rank":"A","objective":"p110-obj-02","tags":["définition"],"difficulty":1,"question":"Entre quelles valeurs se situe la durée totale de sommeil normale chez l'être humain ?","answer":"Entre 6 et 10 heures par jour","accept":["6 à 10 heures","6 à 10 h","6-10 h","6 à 10","entre 6 et 10 heures"],"keywords":["6","10"],"explanation":"La durée totale de sommeil normale est comprise entre 6 et 10 heures par jour ; elle est plus longue chez l'enfant que chez l'adulte.","src":"p. 19"},{"id":"p110-qroc-004","type":"QROC","rank":"A","objective":"p110-obj-02","tags":["définition"],"difficulty":2,"question":"Quelle proportion du temps total de sommeil représente normalement le sommeil paradoxal ?","answer":"20 à 25 %","accept":["20-25 %","20 à 25","entre 20 et 25 %","20 à 25 pour cent"],"keywords":["20","25"],"explanation":"Une pathologie du sommeil perturbe son architecture en réduisant le sommeil lent profond (durée normale 90 à 120 minutes), en réduisant le sommeil paradoxal ou en fragmentant le sommeil.","src":"p. 19"},{"id":"p110-qroc-005","type":"QROC","rank":"A","objective":"p110-obj-03","tags":["définition","pédiatrie"],"difficulty":1,"question":"Comment évolue la durée de sommeil par jour de la naissance à l'adolescence ?","answer":"Elle passe de 16 h à 9 h par jour","accept":["16 h à 9 h","16h à 9h","de 16 à 9 heures","16 à 9 heures"],"keywords":["16","9"],"explanation":"Le sommeil de l'adulte est plus court que celui de l'enfant, et les cycles du sommeil alternent plus rapidement chez l'enfant.","src":"p. 19"},{"id":"p110-qroc-006","type":"QROC","rank":"A","objective":"p110-obj-04","tags":["définition"],"difficulty":2,"question":"Quels sont les trois grands types de troubles respiratoires du sommeil ?","answer":"SAHOS, SAHCS et hypoventilation alvéolaire nocturne","accept":["sahos, sahcs, hypoventilation alvéolaire nocturne","sahos sahcs hypoventilation alvéolaire nocturne","syndrome d'apnées hypopnées obstructives, syndrome d'apnées hypopnées centrales et hypoventilation alvéolaire nocturne"],"keywords":["sahos","sahcs","hypoventilation"],"explanation":"Obstructif : occlusions répétées des voies aériennes supérieures ; central : diminutions ou abolitions répétées de la commande ventilatoire ; hypoventilation alvéolaire nocturne : ventilation insuffisante avec hausse du CO2 et hypoxémie.","src":"p. 19"},{"id":"p110-qroc-007","type":"QROC","rank":"A","objective":"p110-obj-04","tags":["définition","physiopathologie"],"difficulty":2,"question":"Quel syndrome du sommeil résulte de diminutions ou d'abolitions répétées de la commande ventilatoire centrale ?","answer":"Le SAHCS (syndrome d'apnées hypopnées centrales)","accept":["sahcs","syndrome d'apnées hypopnées centrales du sommeil","apnées centrales du sommeil","syndrome d'apnées hypopnées centrales"],"keywords":["central"],"explanation":"Il est beaucoup moins fréquent que le SAHOS (environ 10 % des syndromes d'apnées du sommeil) et impose un bilan étiologique (cardiologique, neurologique, médicaments) et un traitement spécifique.","src":"p. 18-19"},{"id":"p110-qroc-008","type":"QROC","rank":"A","objective":"p110-obj-04","tags":["définition","biologie"],"difficulty":2,"question":"Quelles anomalies gazeuses caractérisent l'hypoventilation alvéolaire nocturne ?","answer":"Hausse du CO2 et hypoxémie nocturne","accept":["augmentation du gaz carbonique et hypoxémie","hypercapnie et hypoxémie","hypercapnie hypoxémie nocturne","augmentation du co2 et hypoxémie nocturne"],"keywords":["hypox"],"explanation":"Elle complique les pathologies respiratoires sévères obstructives (BPCO) ou restrictives (obésité, maladies neuromusculaires) et peut évoluer vers une hypoventilation alvéolaire diurne.","src":"p. 19"},{"id":"p110-qroc-009","type":"QROC","rank":"A","objective":"p110-obj-05","tags":["définition","diagnostic"],"difficulty":1,"question":"Comment se définit une apnée obstructive ?","answer":"Arrêt du flux aérien ≥ 10 s avec efforts ventilatoires persistants","accept":["arrêt du débit aérien naso-buccal pendant au moins 10 secondes avec persistance d'efforts ventilatoires","arrêt du flux aérien d'au moins 10 secondes avec efforts ventilatoires","arrêt du débit aérien d'au moins 10 secondes avec efforts ventilatoires"],"keywords":["10","effort"],"explanation":"Une obstruction complète des voies aériennes supérieures correspond à une apnée, une obstruction incomplète à une hypopnée.","src":"p. 19-20"},{"id":"p110-qroc-010","type":"QROC","rank":"A","objective":"p110-obj-05","tags":["définition","diagnostic"],"difficulty":2,"question":"Comment se définit une hypopnée ?","answer":"Baisse de ventilation > 30 % ≥ 10 s + désaturation ≥ 3 % et/ou micro-éveil","accept":["diminution de la ventilation de plus de 30 % pendant au moins 10 secondes avec désaturation d'au moins 3 % et/ou micro-éveil","baisse de la ventilation > 30 % pendant 10 secondes avec désaturation de 3 % ou micro-éveil","ventilation diminuée de plus de 30 % pendant au moins 10 secondes avec désaturation d'au moins 3 % ou micro-éveil"],"keywords":["30","10","désaturation"],"explanation":"Le micro-éveil n'est identifiable qu'avec une polysomnographie, pas avec la polygraphie ventilatoire.","src":"p. 20"},{"id":"p110-qroc-011","type":"QROC","rank":"A","objective":"p110-obj-05","tags":["définition"],"difficulty":1,"question":"Que signifie le sigle IAH utilisé pour quantifier les événements respiratoires du sommeil ?","answer":"Index d'apnées-hypopnées (événements par heure)","accept":["index d'apnées hypopnées","index d'apnées-hypopnées","indice d'apnées hypopnées","nombre d'apnées et d'hypopnées par heure"],"keywords":["apn","hypopn"],"explanation":"L'IAH est le nombre d'apnées et d'hypopnées rapporté au temps d'enregistrement (polygraphie ventilatoire) ou au temps de sommeil (polysomnographie).","src":"p. 20"},{"id":"p110-qroc-012","type":"QROC","rank":"A","objective":"p110-obj-05","tags":["définition","diagnostic"],"difficulty":1,"question":"À partir de quel IAH le critère polygraphique ou polysomnographique (critère C) du SAHOS est-il rempli ?","answer":"IAH ≥ 5 par heure","accept":["5","≥ 5","au moins 5","supérieur ou égal à 5","iah ≥ 5"],"keywords":["5"],"explanation":"Le SAHOS est défini par le critère clinique A ou B, associé au critère C (IAH ≥ 5 par heure).","src":"p. 21"},{"id":"p110-qroc-013","type":"QROC","rank":"A","objective":"p110-obj-05","tags":["définition","clinique"],"difficulty":2,"question":"Dans la définition du SAHOS, quel signe clinique isolé (critère A), non expliqué par d'autres facteurs, suffit en association avec un IAH ≥ 5 ?","answer":"Une somnolence diurne excessive","accept":["somnolence diurne excessive","somnolence diurne","somnolence excessive","somnolence"],"keywords":["somnolence"],"explanation":"Critère B (à la place de A) : au moins 2 signes parmi ronflement sévère quotidien, étouffements ou suffocations nocturnes, éveils répétés, sommeil non réparateur, fatigue diurne, difficultés de concentration, nycturie.","src":"p. 21"},{"id":"p110-qroc-014","type":"QROC","rank":"A","objective":"p110-obj-05","tags":["définition","diagnostic"],"difficulty":1,"question":"À partir de quel IAH le SAHOS est-il qualifié de sévère ?","answer":"IAH ≥ 30 par heure","accept":["30","≥ 30","30 par heure","au moins 30","supérieur ou égal à 30"],"keywords":["30"],"explanation":"Légère : 5 à 14/h ; modérée : 15 à 29/h ; sévère : ≥ 30/h. Le retentissement de la somnolence sur les activités quotidiennes et les comorbidités cardio-vasculaires ou respiratoires sévères entrent aussi dans l'évaluation de la sévérité.","src":"p. 21"},{"id":"p110-qroc-015","type":"QROC","rank":"A","objective":"p110-obj-05","tags":["physiopathologie"],"difficulty":1,"question":"Quel est le siège principal de l'obstruction des voies aériennes dans le SAHOS ?","answer":"Le pharynx (voile du palais, base de langue)","accept":["pharynx","le pharynx","voile du palais","base de langue"],"keywords":["pharyn"],"explanation":"Chez les patients atteints de SAHOS, la contraction des muscles dilatateurs du pharynx est insuffisante pour s'opposer au collapsus des voies aériennes pendant le sommeil.","src":"p. 19"},{"id":"p110-qroc-016","type":"QROC","rank":"A","objective":"p110-obj-05","tags":["physiopathologie"],"difficulty":2,"question":"Quel phénomène, souvent non perçu par le patient, lève l'obstruction pharyngée mais fragmente le sommeil ?","answer":"Le micro-éveil","accept":["micro-éveil","micro éveil","les micro-éveils","micro-éveils"],"keywords":["micro"],"explanation":"Chaque micro-éveil (3 à 15 secondes) rigidifie le pharynx et relance la ventilation ; leur répétition fragmente le sommeil et réduit le sommeil lent profond et paradoxal, d'où un sommeil non réparateur.","src":"p. 20"},{"id":"p110-qroc-017","type":"QROC","rank":"A","objective":"p110-obj-05","tags":["physiopathologie","complications"],"difficulty":2,"question":"Outre la fragmentation du sommeil, quels deux phénomènes du SAHOS augmentent le risque cardio-vasculaire ?","answer":"Hypoxémie intermittente et activation répétée du système sympathique","accept":["hypoxémie intermittente et activation du système sympathique","hypoxémie intermittente et activation sympathique","hypoxémie et activation sympathique"],"keywords":["hypox","sympath"],"explanation":"Ils contribuent aux comorbidités cardio-vasculaires (HTA, coronaropathie, AVC, insuffisance cardiaque, troubles du rythme) et métaboliques (diabète).","src":"p. 20, 22"},{"id":"p110-qroc-018","type":"QROC","rank":"A","objective":"p110-obj-14","tags":["étiologie"],"difficulty":1,"question":"Quel est le principal facteur de risque de SAHOS ?","answer":"L'obésité","accept":["obésité","l'obésité"],"keywords":["obés"],"explanation":"L'IAH est corrélé à l'IMC. Les autres facteurs sont le sexe masculin, l'âge et les anomalies anatomiques des VAS (rétrognathie, micromandibulie, hypertrophie amygdalienne, macroglossie).","src":"p. 18, 21"},{"id":"p110-qroc-019","type":"QROC","rank":"A","objective":"p110-obj-14","tags":["étiologie","épidémiologie"],"difficulty":1,"question":"Chez la femme, à quelle période de la vie la prévalence du SAHOS augmente-t-elle ?","answer":"Après la ménopause","accept":["ménopause","après la ménopause","post-ménopause"],"keywords":["ménopause"],"explanation":"Le SAHOS prédomine chez l'homme et sa prévalence augmente avec l'âge ; chez la femme, elle augmente après la ménopause.","src":"p. 21"},{"id":"p110-qroc-020","type":"QROC","rank":"A","objective":"p110-obj-14","tags":["étiologie","épidémiologie"],"difficulty":2,"question":"Dans quelles situations cardio-métaboliques la prévalence du SAHOS est-elle particulièrement élevée ?","answer":"Syndrome métabolique et HTA résistante","accept":["syndrome métabolique et hta résistante","hta résistante et syndrome métabolique","syndrome métabolique, hta résistante"],"keywords":["métabol","résistante"],"explanation":"Ces contextes, comme le sexe, l'âge, l'IMC et les comorbidités cardio-vasculaires, doivent faire suspecter un SAHOS.","src":"p. 22"},{"id":"p110-qroc-021","type":"QROC","rank":"A","objective":"p110-obj-09","tags":["clinique"],"difficulty":1,"question":"Quel signe nocturne, constaté par l'entourage, est évocateur de SAHOS en plus du ronflement ?","answer":"Des pauses respiratoires pendant le sommeil","accept":["pauses respiratoires","les pauses respiratoires","pauses respiratoires constatées par l'entourage"],"keywords":["pause"],"explanation":"Autres symptômes nocturnes : sensations d'étouffement ou de suffocation, agitation nocturne ou insomnie, nycturie (plus d'une miction par nuit).","src":"p. 22"},{"id":"p110-qroc-022","type":"QROC","rank":"A","objective":"p110-obj-09","tags":["clinique"],"difficulty":1,"question":"Comment s'appelle le symptôme diurne correspondant à un besoin non désiré, parfois incontrôlable, de dormir dans la journée ?","answer":"La somnolence diurne excessive","accept":["somnolence diurne excessive","somnolence diurne","somnolence excessive","somnolence"],"keywords":["somnolence"],"explanation":"Ce besoin de sommeil ne se traduit pas forcément par une sieste ; il est évalué à l'interrogatoire, éventuellement aidé d'auto-questionnaires comme l'échelle d'Epworth.","src":"p. 22"},{"id":"p110-qroc-023","type":"QROC","rank":"A","objective":"p110-obj-09","tags":["clinique"],"difficulty":1,"question":"Quel type de céphalées fait partie des symptômes diurnes évocateurs de SAHOS ?","answer":"Les céphalées matinales","accept":["céphalées matinales","matinales","céphalées du matin"],"keywords":["matinal"],"explanation":"Autres symptômes diurnes : somnolence excessive, asthénie (encore moins spécifique), troubles cognitifs (mémoire, concentration) et troubles de la libido.","src":"p. 22"},{"id":"p110-qroc-024","type":"QROC","rank":"B","objective":"p110-obj-06","tags":["diagnostic","clinique"],"difficulty":2,"question":"À partir de quel score de l'échelle d'Epworth parle-t-on de somnolence diurne excessive ?","answer":"Score ≥ 11 sur 24","accept":["11","≥ 11","11/24","supérieur ou égal à 11","au moins 11"],"keywords":["11"],"explanation":"L'échelle d'Epworth (score de 0 à 24) quantifie la somnolence mais ne dépiste pas le SAS ; seuls 50 % des patients ayant un SAHOS ont un score supérieur à 10.","src":"p. 22-23"},{"id":"p110-qroc-025","type":"QROC","rank":"A","objective":"p110-obj-11","tags":["clinique","pédiatrie"],"difficulty":1,"question":"Quel examen systématique faut-il pratiquer chez un enfant dont les parents rapportent un ronflement ?","answer":"L'examen des amygdales","accept":["amygdales","examen des amygdales","l'examen des amygdales","examen orl des amygdales"],"keywords":["amygdal"],"explanation":"L'hypertrophie amygdalienne et vélaire diminue le calibre des voies aériennes supérieures, en particulier chez l'enfant.","src":"p. 20, 24"},{"id":"p110-qroc-026","type":"QROC","rank":"A","objective":"p110-obj-11","tags":["clinique","pédiatrie"],"difficulty":2,"question":"Outre un ronflement rapporté par les parents, quelles deux situations imposent l'examen systématique des amygdales chez l'enfant ?","answer":"Cassure de la pente de croissance et troubles des acquisitions","accept":["cassure de la pente de croissance staturo-pondérale et troubles des acquisitions","cassure de la courbe de croissance et troubles des acquisitions","cassure de la croissance staturo-pondérale et hyperactivité ou trouble de l'attention"],"keywords":["croissance","acquisition"],"explanation":"Les troubles des acquisitions comprennent l'hyperactivité et le trouble de l'attention.","src":"p. 24"},{"id":"p110-qroc-027","type":"QROC","rank":"A","objective":"p110-obj-10","tags":["clinique","pédiatrie"],"difficulty":1,"question":"Quel signe clinique peut révéler une hypertrophie des végétations adénoïdes chez l'enfant ?","answer":"Des signes d'occlusion (obstruction) nasale","accept":["occlusion nasale","obstruction nasale","signes d'occlusion nasale"],"keywords":["nasal"],"explanation":"L'hypertrophie des végétations adénoïdes peut contribuer au SAHOS de l'enfant ; l'examen ORL recherche aussi une hypertrophie des amygdales.","src":"p. 24"},{"id":"p110-qroc-028","type":"QROC","rank":"A","objective":"p110-obj-15","tags":["diagnostic","définition"],"difficulty":2,"question":"Quelle fréquence et quelle durée des symptômes nocturnes définissent l'insomnie chronique ?","answer":"Plus de 3 nuits par semaine pendant plus de 3 mois","accept":["plus de 3 nuits par semaine pendant plus de 3 mois","plus de 3 nuits par semaine et plus de 3 mois","plus de 3 nuits/semaine pendant plus de 3 mois"],"keywords":["3 nuits","3 mois"],"explanation":"Les symptômes nocturnes sont une latence d'endormissement > 45 minutes, des difficultés de maintien du sommeil ou des éveils précoces, avec un retentissement diurne (fatigue, troubles de la concentration ou de l'humeur, irritabilité).","src":"p. 23"},{"id":"p110-qroc-029","type":"QROC","rank":"A","objective":"p110-obj-15","tags":["diagnostic"],"difficulty":1,"question":"Quelle est la nature du diagnostic d'insomnie chronique ?","answer":"Un diagnostic clinique","accept":["clinique","diagnostic clinique","il est clinique","purement clinique"],"keywords":["clinique"],"explanation":"Le diagnostic repose sur la clinique ; un agenda du sommeil tenu sur 15 jours permet d'objectiver la plainte.","src":"p. 23"},{"id":"p110-qroc-030","type":"QROC","rank":"A","objective":"p110-obj-15","tags":["diagnostic","suivi"],"difficulty":1,"question":"Quel outil, à tenir pendant 15 jours, permet d'objectiver une plainte d'insomnie et sa régularité ?","answer":"L'agenda du sommeil","accept":["agenda du sommeil","un agenda du sommeil","l'agenda du sommeil"],"keywords":["agenda"],"explanation":"Il renseigne les heures de coucher et de lever, la durée d'endormissement, la durée et la fréquence des éveils nocturnes ; c'est aussi un outil de prise en charge.","src":"p. 23"},{"id":"p110-qroc-031","type":"QROC","rank":"A","objective":"p110-obj-15","tags":["diagnostic","pièges"],"difficulty":2,"question":"Quel enregistrement nocturne n'est jamais indiqué dans la prise en charge d'une insomnie ?","answer":"La polygraphie ventilatoire nocturne","accept":["polygraphie ventilatoire","polygraphie","polygraphie ventilatoire nocturne"],"keywords":["polygraph"],"explanation":"La polysomnographie peut en revanche être réalisée en cas de somnolence diurne ou de suspicion d'un trouble associé, comme le SAHOS.","src":"p. 23"},{"id":"p110-qroc-032","type":"QROC","rank":"A","objective":"p110-obj-15","tags":["traitement"],"difficulty":1,"question":"Sur quelle approche repose essentiellement la prise en charge de l'insomnie chronique ?","answer":"La thérapie cognitivo-comportementale (TCC)","accept":["tcc","thérapie cognitivo-comportementale","thérapie cognitivo comportementale","la tcc"],"keywords":["cognitivo"],"explanation":"La TCC permet de restaurer l'efficacité du sommeil ; les règles d'hygiène du sommeil sont essentielles à la prise en charge de tout trouble du sommeil.","src":"p. 23, 26"},{"id":"p110-qroc-033","type":"QROC","rank":"B","objective":"p110-obj-07","tags":["clinique","diagnostic"],"difficulty":1,"question":"Quel syndrome associe un besoin de bouger les membres inférieurs au repos, soulagé par la mobilisation et survenant surtout le soir ou la nuit ?","answer":"Le syndrome des jambes sans repos","accept":["jambes sans repos","syndrome des jambes sans repos","le syndrome des jambes sans repos"],"keywords":["jambes sans repos"],"explanation":"Son diagnostic est clinique ; il touche 10 à 15 % de la population française et est pris en charge s'il retentit sur le sommeil ou la qualité de vie.","src":"p. 23"},{"id":"p110-qroc-034","type":"QROC","rank":"A","objective":"p110-obj-13","tags":["étiologie","pièges"],"difficulty":1,"question":"Quel syndrome psychiatrique est à évoquer en priorité (+++) devant une plainte de trouble du sommeil ou de somnolence diurne ?","answer":"Le syndrome dépressif","accept":["syndrome dépressif","dépression","un syndrome dépressif","trouble dépressif"],"keywords":["dépress"],"explanation":"Autres diagnostics différentiels : dette chronique de sommeil et hygiène du sommeil, somnolence iatrogène (psychotropes, antalgiques), insomnie chronique, hypersomnies centrales, syndrome des jambes sans repos.","src":"p. 23"},{"id":"p110-qroc-035","type":"QROC","rank":"A","objective":"p110-obj-13","tags":["étiologie"],"difficulty":2,"question":"Quelles sont les deux hypersomnies centrales citées parmi les diagnostics différentiels de la somnolence ?","answer":"Narcolepsie et hypersomnie idiopathique","accept":["narcolepsie et hypersomnie idiopathique","narcolepsie, hypersomnie idiopathique","narcolepsie hypersomnie idiopathique"],"keywords":["narcolepsie","idiopathique"],"explanation":"Elles figurent avec la dette chronique de sommeil, la somnolence iatrogène et les troubles psychiatriques parmi les diagnostics différentiels d'une somnolence diurne.","src":"p. 23"},{"id":"p110-qroc-036","type":"QROC","rank":"A","objective":"p110-obj-21","tags":["prévention"],"difficulty":1,"question":"Après quelle heure faut-il éviter le café et les boissons énergisantes pour favoriser le sommeil ?","answer":"Après 14 h","accept":["14 h","14h","après 14 h","après 14h","14 heures"],"keywords":["14"],"explanation":"L'éviction des excitants fait partie des mesures hygiéno-diététiques, essentielles à la prise en charge de tout trouble du sommeil.","src":"p. 26"},{"id":"p110-qroc-037","type":"QROC","rank":"A","objective":"p110-obj-20","tags":["prévention"],"difficulty":1,"question":"Combien de temps avant le coucher faut-il éviter l'exposition aux lumières directes ?","answer":"1 heure avant le coucher","accept":["une heure","1h","1 h","une heure avant le coucher"],"keywords":["1"],"explanation":"Il faut aussi retirer les écrans de la chambre et garder un environnement de sommeil calme, sans lumière, à température fraîche.","src":"p. 26"},{"id":"p110-qroc-038","type":"QROC","rank":"A","objective":"p110-obj-19","tags":["prévention"],"difficulty":1,"question":"Que faut-il retirer de la chambre à coucher dans les règles d'hygiène du sommeil ?","answer":"Les écrans","accept":["écrans","les écrans","écran"],"keywords":["écran"],"explanation":"Les écrans sont retirés de la chambre, et l'on évite l'exposition aux lumières directes une heure avant le coucher.","src":"p. 26"},{"id":"p110-qroc-039","type":"QROC","rank":"B","objective":"p110-obj-23","tags":["traitement"],"difficulty":1,"question":"Quel est le traitement le plus efficace à ce jour pour éviter les apnées et hypopnées obstructives du sommeil ?","answer":"La pression positive continue (PPC)","accept":["ppc","la ppc","pression positive continue"],"keywords":["positive"],"explanation":"L'air pressurisé, appliqué par un masque, agit comme une attelle pneumatique des voies aériennes supérieures.","src":"p. 26"},{"id":"p110-qroc-040","type":"QROC","rank":"B","objective":"p110-obj-23","tags":["traitement"],"difficulty":2,"question":"Chez un patient symptomatique, à partir de quel IAH la PPC est-elle indiquée en première intention sans autre critère ?","answer":"IAH ≥ 30 par heure","accept":["30","≥ 30","iah ≥ 30","au moins 30","30 par heure"],"keywords":["30"],"explanation":"Entre 15 et 29 par heure, la PPC est indiquée en première intention en cas de somnolence sévère (et/ou de risque accidentel) ou de comorbidités cardio-vasculaires ou respiratoires graves.","src":"p. 21, 28"},{"id":"p110-qroc-041","type":"QROC","rank":"B","objective":"p110-obj-23","tags":["traitement"],"difficulty":2,"question":"Quel traitement est indiqué en seconde intention en cas de refus ou d'intolérance à la PPC ?","answer":"L'orthèse d'avancée mandibulaire (OAM)","accept":["oam","orthèse d'avancée mandibulaire","orthèse mandibulaire","l'oam"],"keywords":["mandibul"],"explanation":"L'OAM est indiquée en première intention pour 15 ≤ IAH < 30 sans somnolence sévère ni comorbidité grave, en l'absence de contre-indication dentaire ou maxillo-faciale.","src":"p. 28"},{"id":"p110-qroc-042","type":"QROC","rank":"B","objective":"p110-obj-16","tags":["diagnostic","paraclinique"],"difficulty":1,"question":"Quel examen est de première intention en cas de suspicion de SAHOS ?","answer":"La polygraphie ventilatoire","accept":["polygraphie ventilatoire","polygraphie","la polygraphie ventilatoire"],"keywords":["polygraph"],"explanation":"Elle comprend le flux aérien (canules nasales), les efforts respiratoires (sangles thoracique et abdominale) et l'oxymétrie de pouls.","src":"p. 24"},{"id":"p110-qroc-043","type":"QROC","rank":"B","objective":"p110-obj-16","tags":["diagnostic","paraclinique"],"difficulty":1,"question":"Quel examen est considéré comme l'examen de référence (gold standard) du SAHOS ?","answer":"La polysomnographie","accept":["polysomnographie","psg","la polysomnographie"],"keywords":["polysomno"],"explanation":"Plus complète, plus longue et plus onéreuse, elle est proposée dans les situations cliniques complexes ou en deuxième intention si la polygraphie n'a pas permis de conclure.","src":"p. 25"},{"id":"p110-qroc-044","type":"QROC","rank":"B","objective":"p110-obj-22","tags":["complications","pièges"],"difficulty":1,"question":"Quelle conséquence l'hypersomnolence a-t-elle sur la conduite automobile ?","answer":"Elle contre-indique la conduite automobile","accept":["contre-indication","contre-indication à la conduite","contre-indication à la conduite automobile","contre indique la conduite"],"keywords":["contre"],"explanation":"Une interruption temporaire du travail doit être envisagée chez les conducteurs professionnels ; la reprise est possible après un mois de traitement bien conduit.","src":"p. 22"},{"id":"p110-qroc-045","type":"QROC","rank":"A","objective":"p110-obj-01","tags":["étiologie","pédiatrie"],"difficulty":1,"question":"Quelle hypertrophie, particulièrement fréquente chez l'enfant, diminue le calibre des voies aériennes supérieures et favorise le SAHOS ?","answer":"L'hypertrophie amygdalienne (et vélaire)","accept":["hypertrophie amygdalienne","hypertrophie des amygdales","amygdales","hypertrophie amygdalienne et vélaire"],"keywords":["amygdal"],"explanation":"L'hypertrophie des amygdales est visible à l'examen ORL de l'enfant ; l'hypertrophie des végétations adénoïdes (occlusion nasale) peut aussi contribuer au SAHOS de l'enfant.","src":"p. 20, 24"},{"id":"p110-qcm-101","type":"QRM","rank":"A","objective":"p110-obj-02","tags":["définition"],"difficulty":1,"stem":"Concernant l'architecture du sommeil normal de l'adulte, quelles propositions sont exactes ?","options":[{"t":"On compte habituellement 10 à 12 cycles au cours d'une nuit","ok":false,"why":"Un sommeil normal comporte 4 à 6 cycles."},{"t":"Un cycle dure en général entre 90 et 110 minutes","ok":true,"why":"Les trois stades (léger, profond, paradoxal) forment un cycle de 90 à 110 minutes."},{"t":"Le sommeil paradoxal représente normalement la moitié du temps total de sommeil","ok":false,"why":"Il représente normalement 20 à 25 % du temps total de sommeil."},{"t":"Le sommeil comprend trois stades : léger, profond et paradoxal","ok":true,"why":"Ces trois stades alternent pour former un cycle."},{"t":"La durée totale de sommeil normale est de 2 à 4 heures par jour","ok":false,"why":"Elle est comprise entre 6 et 10 heures par jour."}],"explanation":"Sommeil normal : durée totale de 6 à 10 h par jour, trois stades (léger, profond, paradoxal), cycles de 90 à 110 minutes, 4 à 6 cycles par nuit, sommeil paradoxal = 20 à 25 % du temps total.","src":"p. 19"},{"id":"p110-qcm-102","type":"QRM","rank":"A","objective":"p110-obj-03","tags":["définition","pédiatrie"],"difficulty":1,"stem":"Concernant le sommeil de l'enfant par rapport à celui de l'adulte, quelles propositions sont exactes ?","options":[{"t":"La durée de sommeil passe de 16 h par jour (naissance) à 9 h (adolescence)","ok":true,"why":"Le sommeil de l'enfant est plus long que celui de l'adulte."},{"t":"Les cycles du sommeil alternent plus lentement","ok":false,"why":"Ils alternent plus rapidement chez l'enfant."},{"t":"Le sommeil de l'adulte est généralement plus long que celui de l'enfant","ok":false,"why":"Le sommeil de l'adulte est généralement plus court."},{"t":"La durée de sommeil reste identique de la naissance à l'âge adulte","ok":false,"why":"Elle diminue de 16 h par jour à la naissance à 9 h par jour à l'adolescence."},{"t":"Les cycles du sommeil alternent plus rapidement","ok":true,"why":"C'est une spécificité pédiatrique du sommeil."}],"explanation":"De la naissance à l'adolescence, la durée de sommeil passe de 16 h à 9 h par jour, et les cycles alternent plus rapidement que chez l'adulte.","src":"p. 19"},{"id":"p110-qcm-103","type":"QRM","rank":"A","objective":"p110-obj-04","tags":["définition"],"difficulty":2,"stem":"À propos des troubles respiratoires du sommeil, quelle proposition est exacte ?","options":[{"t":"Le SAHCS est plus fréquent que le SAHOS","ok":false,"why":"Le SAHCS est beaucoup moins fréquent (environ 10 % des syndromes d'apnées du sommeil)."},{"t":"L'hypoventilation alvéolaire nocturne se traduit par une baisse du taux de gaz carbonique","ok":false,"why":"Elle se traduit par une augmentation du gaz carbonique et une hypoxémie nocturne."},{"t":"Le SAHOS se caractérise par une abolition répétée de la commande ventilatoire centrale","ok":false,"why":"C'est le SAHCS ; le SAHOS correspond à des occlusions répétées des voies aériennes supérieures."},{"t":"Le SAHCS impose un bilan étiologique (cardiologique, neurologique, médicaments)","ok":true,"why":"Il nécessite un bilan étiologique et un traitement spécifique."},{"t":"L'hypoventilation alvéolaire nocturne ne complique que les pathologies respiratoires obstructives","ok":false,"why":"Elle complique aussi les pathologies restrictives (obésité, maladies neuromusculaires)."}],"explanation":"Trois types de troubles respiratoires du sommeil : SAHOS (occlusions des VAS), SAHCS (commande ventilatoire centrale, environ 10 % des SAS, bilan étiologique) et hypoventilation alvéolaire nocturne (hausse du CO2, hypoxémie).","src":"p. 18-19"},{"id":"p110-qcm-104","type":"QRM","rank":"A","objective":"p110-obj-05","tags":["définition","diagnostic"],"difficulty":2,"stem":"À propos de la définition des événements respiratoires du SAHOS, quelles propositions sont exactes ?","options":[{"t":"Une apnée correspond à une obstruction incomplète des voies aériennes supérieures","ok":false,"why":"L'apnée est une obstruction complète ; l'obstruction incomplète est l'hypopnée."},{"t":"Une apnée obstructive est un arrêt du flux aérien d'au moins 10 s avec efforts ventilatoires persistants","ok":true,"why":"Les efforts ventilatoires persistent pendant l'apnée obstructive."},{"t":"Le micro-éveil d'une hypopnée est identifiable par la polygraphie ventilatoire","ok":false,"why":"Il n'est identifiable qu'avec une polysomnographie."},{"t":"Une hypopnée est une baisse de ventilation de plus de 30 % pendant au moins 30 secondes","ok":false,"why":"La baisse doit durer au moins 10 secondes."},{"t":"Hypopnée : baisse de ventilation > 30 % pendant ≥ 10 s avec désaturation ≥ 3 % et/ou micro-éveil","ok":true,"why":"C'est la définition de l'hypopnée."}],"explanation":"Apnée = obstruction complète, hypopnée = obstruction incomplète. Apnée obstructive : arrêt ≥ 10 s avec efforts ventilatoires. Hypopnée : baisse > 30 % pendant ≥ 10 s avec désaturation ≥ 3 % et/ou micro-éveil (visible seulement en polysomnographie).","src":"p. 19-20"},{"id":"p110-qcm-105","type":"QRM","rank":"A","objective":"p110-obj-05","tags":["définition","diagnostic"],"difficulty":2,"stem":"Selon la définition du SAHOS, quelles propositions sont exactes ?","options":[{"t":"Le diagnostic repose uniquement sur les signes cliniques","ok":false,"why":"Il faut aussi un critère polysomnographique ou polygraphique (IAH ≥ 5)."},{"t":"Il faut un critère clinique (A ou B) et un critère polygraphique ou polysomnographique (C)","ok":true,"why":"La définition associe signes évocateurs et quantité anormale d'événements obstructifs."},{"t":"Le critère C est un IAH supérieur ou égal à 15 par heure","ok":false,"why":"Le seuil est de 5 par heure ; 15 correspond au début de la forme modérée."},{"t":"Le critère C est un IAH supérieur ou égal à 5 par heure","ok":true,"why":"IAH ≥ 5 est le critère C."},{"t":"La somnolence diurne excessive est indispensable pour poser le diagnostic","ok":false,"why":"Elle constitue le critère A, mais le critère B (au moins 2 autres signes) peut la remplacer."}],"explanation":"SAHOS = critère A (somnolence diurne excessive) ou B (au moins 2 signes parmi ronflement sévère quotidien, étouffements nocturnes, éveils répétés, sommeil non réparateur, fatigue diurne, difficultés de concentration, nycturie) + critère C (IAH ≥ 5 par heure).","src":"p. 21"},{"id":"p110-qcm-106","type":"QRM","rank":"A","objective":"p110-obj-05","tags":["physiopathologie"],"difficulty":2,"stem":"Concernant la physiopathologie du SAHOS, quelle proposition est exacte ?","options":[{"t":"La contraction des muscles dilatateurs du pharynx est excessive pendant le sommeil","ok":false,"why":"Elle est insuffisante pour lutter contre le collapsus des voies aériennes."},{"t":"Chaque obstruction ne se lève que par un micro-éveil qui rigidifie le pharynx","ok":true,"why":"Le micro-éveil (3 à 15 secondes) permet la rigidification du pharynx et la reprise ventilatoire."},{"t":"L'obstruction siège principalement au niveau de la trachée et des bronches","ok":false,"why":"Le siège principal est le pharynx (voile du palais, base de langue)."},{"t":"Les micro-éveils sont presque toujours perçus par le patient qui s'en plaint","ok":false,"why":"Ils sont souvent non perçus par le patient."},{"t":"Les micro-éveils augmentent la durée de sommeil lent profond et paradoxal","ok":false,"why":"Ils réduisent le temps passé en sommeil lent profond et paradoxal, au profit du sommeil lent léger."}],"explanation":"Obstruction pharyngée intermittente (apnée si complète, hypopnée si incomplète) : insuffisance des muscles dilatateurs, micro-éveils répétés, fragmentation du sommeil, hypoxémie intermittente et activation sympathique.","src":"p. 19-20"},{"id":"p110-qcm-107","type":"QRM","rank":"A","objective":"p110-obj-14","tags":["étiologie"],"difficulty":2,"stem":"Parmi les facteurs suivants, lesquels sont des facteurs de risque de SAHOS ?","options":[{"t":"L'obésité","ok":true,"why":"C'est le principal facteur de risque, l'IAH étant corrélé à l'IMC."},{"t":"Un calibre élargi des voies aériennes supérieures","ok":false,"why":"Le SAHOS est favorisé par une diminution anatomique du calibre des VAS."},{"t":"Le sexe masculin","ok":true,"why":"Le SAHOS prédomine chez l'homme."},{"t":"La jeunesse : la prévalence diminue avec l'âge","ok":false,"why":"La prévalence augmente avec l'âge."},{"t":"La macroglossie","ok":true,"why":"Elle fait partie des anomalies anatomiques des VAS favorisant le SAHOS."}],"explanation":"Facteurs de risque : obésité (principal), sexe masculin, âge, ménopause chez la femme, anomalies anatomiques des VAS (rétrognathie, micromandibulie, hypertrophie amygdalienne, macroglossie).","src":"p. 18, 21"},{"id":"p110-qcm-108","type":"QRM","rank":"A","objective":"p110-obj-14","tags":["complications"],"difficulty":2,"stem":"Le SAHOS favorise le développement de quelles comorbidités ou complications ?","options":[{"t":"L'hypertension artérielle","ok":true,"why":"Du fait des désaturations et des micro-éveils, le SAHOS favorise l'HTA."},{"t":"Le diabète","ok":true,"why":"Il fait partie des comorbidités métaboliques favorisées."},{"t":"Une diminution du risque d'accident de la voie publique","ok":false,"why":"Le SAHOS augmente le risque d'accident de la voie publique et du travail."},{"t":"Les troubles du rythme cardiaque","ok":true,"why":"Ils figurent parmi les pathologies cardio-vasculaires favorisées."},{"t":"Les accidents vasculaires cérébraux","ok":true,"why":"Ils figurent parmi les pathologies cardio-vasculaires favorisées."}],"explanation":"Le SAHOS favorise HTA, diabète et pathologies cardio-vasculaires (coronaropathie, AVC, insuffisance cardiaque, troubles du rythme), et augmente le risque d'accident de la voie publique et du travail.","src":"p. 21-22"},{"id":"p110-qcm-109","type":"QRM","rank":"A","objective":"p110-obj-09","tags":["clinique"],"difficulty":2,"stem":"Un homme de 52 ans, obèse, consulte pour une somnolence diurne ; son épouse décrit des ronflements bruyants. Parmi les éléments suivants, lesquels sont évocateurs d'un SAHOS ?","options":[{"t":"Des pauses respiratoires pendant le sommeil constatées par l'épouse","ok":true,"why":"Symptôme nocturne évocateur, rapporté par l'entourage."},{"t":"Un besoin de bouger les jambes au repos, soulagé par la mobilisation","ok":false,"why":"Ce tableau évoque un syndrome des jambes sans repos."},{"t":"Des céphalées matinales","ok":true,"why":"Elles font partie des symptômes diurnes évocateurs."},{"t":"Des troubles de la libido","ok":true,"why":"Ils font partie des symptômes diurnes du SAHOS."},{"t":"Une nycturie, avec plus d'une miction par nuit","ok":true,"why":"La nycturie fait partie des symptômes nocturnes."}],"explanation":"Symptômes nocturnes : ronflements, pauses respiratoires constatées par l'entourage, sensations d'étouffement ou de suffocation, agitation nocturne ou insomnie, nycturie. Symptômes diurnes : somnolence excessive, asthénie, troubles cognitifs, troubles de la libido, céphalées matinales.","src":"p. 22"},{"id":"p110-qcm-110","type":"QRM","rank":"B","objective":"p110-obj-06","tags":["diagnostic","clinique"],"difficulty":2,"stem":"À propos de l'échelle de somnolence d'Epworth, quelles propositions sont exactes ?","options":[{"t":"C'est un outil de dépistage du SAS","ok":false,"why":"Elle quantifie la somnolence mais ne dépiste pas le SAS."},{"t":"Un score supérieur ou égal à 11 sur 24 traduit une somnolence diurne excessive","ok":true,"why":"Le score va de 0 à 24 ; ≥ 11 est pathologique."},{"t":"Un score normal élimine le diagnostic de SAHOS","ok":false,"why":"Seuls 50 % des patients ayant un SAHOS ont une somnolence excessive : il faut rechercher les autres symptômes."},{"t":"Seuls 50 % des patients ayant un SAHOS ont un score supérieur à 10","ok":true,"why":"D'où la nécessité d'interroger correctement le patient sur les autres symptômes."},{"t":"Elle remplace l'interrogatoire des troubles de vigilance diurne","ok":false,"why":"Elle ne remplace pas un interrogatoire correct."}],"explanation":"L'échelle d'Epworth (0 à 24) est l'outil le plus utilisé pour quantifier la somnolence ; un score ≥ 11 est pathologique, mais la somnolence est absente chez la moitié des patients ayant un SAHOS.","src":"p. 22-23"},{"id":"p110-qcm-111","type":"QRM","rank":"B","objective":"p110-obj-16","tags":["diagnostic","paraclinique"],"difficulty":2,"stem":"Quels éléments comprend la polygraphie ventilatoire ?","options":[{"t":"Un électroencéphalogramme","ok":false,"why":"L'EEG fait partie de la polysomnographie."},{"t":"Un enregistrement du flux aérien par des canules de pression nasale","ok":true,"why":"Il permet d'identifier les apnées et hypopnées."},{"t":"Des sangles thoracique et abdominale analysant les efforts respiratoires","ok":true,"why":"Elles précisent le caractère obstructif ou central des événements."},{"t":"Un électro-oculogramme","ok":false,"why":"L'électro-oculogramme fait partie de la polysomnographie."},{"t":"Un oxymètre de pouls détectant les désaturations","ok":true,"why":"Il détecte les désaturations associées aux apnées et hypopnées."}],"explanation":"La polygraphie ventilatoire (première intention) enregistre flux aérien, efforts respiratoires et oxymétrie ; la polysomnographie y ajoute un électroencéphalogramme, un électro-oculogramme et un électro-myogramme mentonnier (± jambier) pour analyser le sommeil.","src":"p. 24-25"},{"id":"p110-qcm-112","type":"QRM","rank":"A","objective":"p110-obj-15","tags":["diagnostic","définition"],"difficulty":2,"stem":"À propos de l'insomnie chronique, quelles propositions sont exactes ?","options":[{"t":"Elle suppose des symptômes nocturnes plus de 3 nuits par semaine pendant plus de 3 mois","ok":true,"why":"C'est la durée et la fréquence qui définissent l'insomnie chronique."},{"t":"Son diagnostic nécessite une polygraphie ventilatoire nocturne","ok":false,"why":"La polygraphie ventilatoire n'est jamais indiquée dans la prise en charge de l'insomnie."},{"t":"Le diagnostic est clinique","ok":true,"why":"Un agenda du sommeil sur 15 jours permet d'objectiver la plainte."},{"t":"Une latence d'endormissement supérieure à 15 minutes suffit à la définir","ok":false,"why":"Le Collège retient une latence d'endormissement supérieure à 45 minutes parmi les symptômes."},{"t":"Sa prise en charge repose essentiellement sur une thérapie cognitivo-comportementale","ok":true,"why":"Elle permet de restaurer l'efficacité du sommeil."}],"explanation":"Insomnie chronique : symptômes nocturnes (latence d'endormissement > 45 min, difficultés de maintien du sommeil, éveils précoces) plus de 3 nuits par semaine pendant plus de 3 mois, avec retentissement diurne ; diagnostic clinique ; prise en charge par TCC.","src":"p. 23"},{"id":"p110-qcm-113","type":"QRM","rank":"A","objective":"p110-obj-15","tags":["diagnostic","pièges"],"difficulty":2,"stem":"Une femme de 40 ans se plaint depuis 5 mois de difficultés d'endormissement plus de 3 nuits par semaine, avec fatigue et irritabilité dans la journée. Quelle est la démarche la plus adaptée ?","options":[{"t":"Une polygraphie ventilatoire nocturne systématique","ok":false,"why":"Elle n'est jamais indiquée dans la prise en charge de l'insomnie."},{"t":"Une polysomnographie systématique en première intention","ok":false,"why":"Elle n'est envisagée qu'en cas de somnolence diurne ou de suspicion d'un trouble associé comme le SAHOS."},{"t":"Un agenda du sommeil tenu pendant 15 jours","ok":true,"why":"Il objective la plainte, sa régularité, les horaires de coucher et de lever et les éveils nocturnes."},{"t":"La mise en route d'emblée d'une pression positive continue","ok":false,"why":"La PPC traite le SAHOS ; l'insomnie relève surtout d'une thérapie cognitivo-comportementale."},{"t":"Une orthèse d'avancée mandibulaire","ok":false,"why":"L'OAM est un traitement du SAHOS."}],"explanation":"L'insomnie chronique est un diagnostic clinique ; l'agenda du sommeil sur 15 jours objective la plainte et la prise en charge repose essentiellement sur une TCC.","src":"p. 23"},{"id":"p110-qcm-114","type":"QRM","rank":"A","objective":"p110-obj-13","tags":["étiologie"],"difficulty":2,"stem":"Devant une somnolence diurne ou une plainte de trouble du maintien du sommeil, quels diagnostics différentiels faut-il évoquer ?","options":[{"t":"Une hypersomnie centrale comme la narcolepsie","ok":true,"why":"Narcolepsie et hypersomnie idiopathique font partie des hypersomnies centrales citées."},{"t":"Un syndrome dépressif, à écarter d'emblée car il ne perturbe pas le sommeil","ok":false,"why":"Les troubles psychiatriques, syndrome dépressif en tête (+++), sont à évoquer."},{"t":"Une dette chronique de sommeil","ok":true,"why":"Elle fait partie des diagnostics différentiels, avec les problèmes d'hygiène du sommeil."},{"t":"Une somnolence diurne excessive rare dans la population générale","ok":false,"why":"La somnolence diurne excessive est un symptôme fréquent dans la population générale, aux causes nombreuses."},{"t":"Une somnolence iatrogène liée aux psychotropes ou aux antalgiques","ok":true,"why":"Les traitements psychotropes et antalgiques peuvent induire une somnolence."}],"explanation":"Diagnostics différentiels : dette chronique de sommeil et hygiène du sommeil, somnolence iatrogène, insomnie chronique, troubles psychiatriques (syndrome dépressif +++), hypersomnies centrales, syndrome des jambes sans repos.","src":"p. 22-23"},{"id":"p110-qcm-115","type":"QRM","rank":"A","objective":"p110-obj-19","tags":["prévention"],"difficulty":1,"stem":"Parmi les conseils d'hygiène du sommeil suivants, lesquels sont recommandés ?","options":[{"t":"Dormir dans un environnement calme, sans lumière et à température fraîche","ok":true,"why":"C'est le premier élément d'un environnement de sommeil adéquat."},{"t":"Prendre un café en fin d'après-midi pour tenir jusqu'au coucher","ok":false,"why":"Café et boissons énergisantes doivent être évités après 14 h."},{"t":"Retirer les écrans de la chambre à coucher","ok":true,"why":"Le retrait des écrans de la chambre est recommandé."},{"t":"Ignorer sa fatigue pour garder des horaires de coucher imposés","ok":false,"why":"Il faut respecter sa fatigue et son propre rythme de sommeil."},{"t":"Éviter l'exposition aux lumières directes l'heure précédant le coucher","ok":true,"why":"La non-exposition aux lumières directes une heure avant le coucher est recommandée."}],"explanation":"Hygiène du sommeil : environnement adéquat (calme, sans lumière, frais), éviction des excitants après 14 h, respect de la fatigue et du rythme de sommeil, pas de lumière directe 1 h avant le coucher, écrans hors de la chambre.","src":"p. 26"},{"id":"p110-qcm-116","type":"QRM","rank":"B","objective":"p110-obj-23","tags":["traitement"],"difficulty":2,"stem":"Parmi les médicaments et substances suivants, lesquels aggravent le SAHOS et doivent être évités ?","options":[{"t":"Les benzodiazépines","ok":true,"why":"Les psychotropes, dont les benzodiazépines, aggravent le SAHOS."},{"t":"La pression positive continue","ok":false,"why":"C'est un traitement du SAHOS, pas un facteur aggravant."},{"t":"La morphine et ses dérivés","ok":true,"why":"Les antalgiques morphiniques aggravent le SAHOS."},{"t":"L'orthèse d'avancée mandibulaire","ok":false,"why":"C'est un traitement du SAHOS."},{"t":"La prise d'alcool le soir","ok":true,"why":"L'alcool le soir aggrave le SAHOS."}],"explanation":"Parmi les mesures générales : évincer les psychotropes (benzodiazépines), les antalgiques (morphine et dérivés) et l'alcool le soir, qui aggravent le SAHOS.","src":"p. 26"},{"id":"p110-qcm-117","type":"QRM","rank":"B","objective":"p110-obj-23","tags":["traitement"],"difficulty":2,"stem":"À propos de la pression positive continue (PPC), quelles propositions sont exactes ?","options":[{"t":"Sa mise en route est libre, sans entente préalable avec la Sécurité sociale","ok":false,"why":"Elle suppose une demande d'entente préalable et une prescription par certains spécialistes (pneumologues) ou un médecin formé."},{"t":"Elle agit comme une attelle pneumatique grâce à l'air pressurisé appliqué par un masque","ok":true,"why":"L'air pressurisé est appliqué dans les voies aériennes supérieures."},{"t":"Elle dispense de dépister et de traiter les autres facteurs de risque cardio-vasculaires","ok":false,"why":"Le traitement du SAHOS ne suffit pas à corriger l'HTA, le diabète et la dyslipidémie."},{"t":"Son suivi (observance, tolérance, efficacité) se fait avec un prestataire de santé à domicile","ok":true,"why":"Des outils de télémédecine transmettent les données au médecin prescripteur."},{"t":"Elle est associée à une réduction du risque accidentel quand elle est utilisée régulièrement","ok":true,"why":"L'utilisation régulière réduit le risque accidentel."}],"explanation":"La PPC est le traitement le plus efficace à ce jour ; elle améliore somnolence, asthénie, qualité de vie et nycturie, réduit le risque accidentel et pourrait réduire le risque cardio-vasculaire si l'observance est régulière.","src":"p. 26-27"},{"id":"p110-qcm-118","type":"QRM","rank":"B","objective":"p110-obj-22","tags":["complications","pièges"],"difficulty":2,"stem":"Un conducteur de poids lourd est suivi pour un SAHOS avec hypersomnolence. Quelles propositions sont exactes ?","options":[{"t":"L'hypersomnolence est une contre-indication à la conduite automobile","ok":true,"why":"Elle est une contre-indication à la conduite, quelle qu'en soit la cause."},{"t":"La reprise de la conduite est envisageable dès la première nuit de traitement","ok":false,"why":"Elle peut être envisagée après un mois de traitement bien conduit."},{"t":"Pour un permis poids lourds, l'examen clinique seul suffit à autoriser la reprise","ok":false,"why":"Pour un permis poids lourds, un test EEG de maintien d'éveil est nécessaire."},{"t":"Une interruption temporaire du travail doit être envisagée chez un conducteur professionnel","ok":true,"why":"C'est la conduite à tenir chez les conducteurs professionnels."},{"t":"Pour un permis véhicule léger, un test EEG de maintien d'éveil est obligatoire","ok":false,"why":"Pour un permis véhicule léger, l'examen clinique suffit à évaluer l'efficacité."}],"explanation":"Hypersomnolence = contre-indication à la conduite ; interruption temporaire du travail des conducteurs professionnels ; reprise après un mois de traitement bien conduit, évaluée par l'examen clinique (véhicule léger) ou un test EEG de maintien d'éveil (poids lourds).","src":"p. 22"},{"id":"p110-qru-101","type":"QRU","rank":"A","objective":"p110-obj-05","tags":["diagnostic"],"difficulty":1,"stem":"Un patient symptomatique a un IAH à 22 événements par heure. Comment qualifier la sévérité de son SAHOS sur le critère de l'IAH ?","options":[{"t":"Légère (5 à 14 par heure)","ok":false,"why":"22 est supérieur à 14."},{"t":"Sévère (30 par heure ou plus)","ok":false,"why":"22 est inférieur à 30."},{"t":"Modérée (15 à 29 par heure)","ok":true,"why":"22 est compris entre 15 et 29."},{"t":"Absence de SAHOS (moins de 5 par heure)","ok":false,"why":"Le critère C exige un IAH ≥ 5, ce qui est le cas ici."},{"t":"Non classable sans polysomnographie","ok":false,"why":"L'IAH s'obtient aussi par polygraphie ventilatoire, rapporté au temps d'enregistrement."}],"explanation":"Légère : 5 à 14 par heure ; modérée : 15 à 29 ; sévère : ≥ 30. La décision thérapeutique tient aussi compte de la somnolence et des comorbidités.","src":"p. 20-21"},{"id":"p110-qru-102","type":"QRU","rank":"A","objective":"p110-obj-11","tags":["clinique","pédiatrie"],"difficulty":2,"stem":"Un enfant de 5 ans ronfle toutes les nuits, d'après ses parents, et présente une cassure de sa pente de croissance staturo-pondérale. Quel examen clinique doit être systématique ?","options":[{"t":"Le périmètre abdominal","ok":false,"why":"Ce seuil concerne l'obésité abdominale (> 94 cm chez l'homme, > 80 cm chez la femme)."},{"t":"L'échelle de somnolence d'Epworth","ok":false,"why":"Elle quantifie la somnolence et ne remplace pas l'examen ORL."},{"t":"L'examen des amygdales","ok":true,"why":"Il est systématique devant un ronflement rapporté par les parents ou une cassure de la pente de croissance."},{"t":"Une spirométrie","ok":false,"why":"Elle est recommandée chez les fumeurs, les obèses ou en cas de symptômes respiratoires."},{"t":"Un bilan stomatologique","ok":false,"why":"Il est proposé si un traitement par orthèse d'avancée mandibulaire est envisagé."}],"explanation":"L'examen des amygdales est systématique en cas de ronflement rapporté par les parents, de cassure de la pente de croissance staturo-pondérale ou de troubles des acquisitions (hyperactivité, trouble de l'attention).","src":"p. 24"},{"id":"p110-qru-103","type":"QRU","rank":"A","objective":"p110-obj-10","tags":["clinique","pédiatrie"],"difficulty":2,"stem":"Un enfant ronfle et présente des signes d'occlusion nasale. Quelle anomalie, pouvant contribuer à un SAHOS, doit être recherchée ?","options":[{"t":"Une hypertrophie des végétations adénoïdes","ok":true,"why":"Elle peut contribuer au SAHOS de l'enfant et se manifester par des signes d'occlusion nasale."},{"t":"Une rétrognathie avec micromandibulie","ok":false,"why":"C'est une anomalie anatomique favorisant le SAHOS, mais les signes d'occlusion nasale évoquent surtout les végétations adénoïdes."},{"t":"Une macroglossie majeure","ok":false,"why":"C'est une anomalie anatomique des VAS, sans lien avec une occlusion nasale."},{"t":"Une obésité abdominale importante","ok":false,"why":"Elle se définit par le périmètre abdominal ; elle ne se manifeste pas par une occlusion nasale."},{"t":"Un syndrome des jambes sans repos survenant la nuit","ok":false,"why":"Il se traduit par un besoin de bouger les jambes au repos."}],"explanation":"L'examen ORL recherche un obstacle des VAS : rétrognatisme, macroglossie, hypertrophie du palais mou, de la luette et des amygdales ; l'hypertrophie des végétations adénoïdes peut contribuer au SAHOS de l'enfant et se manifester par une occlusion nasale.","src":"p. 24"},{"id":"p110-qru-104","type":"QRU","rank":"A","objective":"p110-obj-04","tags":["définition","épidémiologie"],"difficulty":1,"stem":"Quelle proportion approximative des syndromes d'apnées du sommeil correspond au type central (SAHCS) ?","options":[{"t":"Environ 1 %","ok":false,"why":"Le SAHCS est moins fréquent que le SAHOS, mais pas à ce point."},{"t":"Environ 10 %","ok":true,"why":"Le SAHCS est beaucoup moins fréquent que le SAHOS : environ 10 % des SAS."},{"t":"Environ 30 %","ok":false,"why":"Trop élevé : le SAHCS représente environ 10 % des SAS."},{"t":"Environ 50 %","ok":false,"why":"Le SAHOS est beaucoup plus fréquent que le SAHCS."},{"t":"Environ 90 %","ok":false,"why":"Cette valeur correspond approximativement à la part du SAHOS."}],"explanation":"Le SAHCS (diminutions ou abolitions répétées de la commande ventilatoire) est beaucoup moins fréquent (environ 10 % des SAS) et nécessite un bilan étiologique et un traitement spécifique.","src":"p. 18"},{"id":"p110-qru-105","type":"QRU","rank":"B","objective":"p110-obj-23","tags":["traitement"],"difficulty":2,"stem":"Un patient symptomatique a un IAH à 35 par heure. Quel traitement spécifique est indiqué en première intention ?","options":[{"t":"Une pression positive continue (PPC)","ok":true,"why":"La PPC est indiquée en première intention chez le patient symptomatique avec IAH ≥ 30 par heure."},{"t":"Une orthèse d'avancée mandibulaire","ok":false,"why":"L'OAM est de première intention pour 15 ≤ IAH < 30 sans critère de gravité, ou de seconde intention en cas de refus de la PPC."},{"t":"Une chirurgie d'avancée maxillo-mandibulaire","ok":false,"why":"Elle n'est proposée que chez des sujets bien sélectionnés, en échec de PPC et d'OAM."},{"t":"Une neurostimulation du nerf hypoglosse","ok":false,"why":"C'est un traitement de 3e intention, en cas d'intolérance à la PPC et à l'OAM."},{"t":"Un traitement médicamenteux","ok":false,"why":"Aucun médicament n'est validé dans le traitement du SAHOS."}],"explanation":"PPC en première intention si IAH ≥ 30 par heure (patient symptomatique), ou si 15 ≤ IAH < 30 avec somnolence sévère (et/ou risque accidentel) ou comorbidités cardio-vasculaires ou respiratoires graves.","src":"p. 27-28"},{"id":"p110-qru-106","type":"QRU","rank":"B","objective":"p110-obj-23","tags":["traitement"],"difficulty":3,"stem":"Un patient symptomatique a un IAH à 20 par heure, sans somnolence sévère ni comorbidité cardio-vasculaire ou respiratoire grave, et sans contre-indication dentaire ou maxillo-faciale. Quel traitement est indiqué en première intention ?","options":[{"t":"Une neurostimulation du nerf hypoglosse","ok":false,"why":"Traitement de 3e intention, après intolérance à la PPC et à l'OAM."},{"t":"Une pression positive continue","ok":false,"why":"Pour 15 ≤ IAH < 30, la PPC est de première intention seulement en cas de somnolence sévère (et/ou risque accidentel) ou de comorbidités graves."},{"t":"Une chirurgie vélo-amygdalienne","ok":false,"why":"Elle concerne une hypertrophie amygdalienne majeure, surtout en pédiatrie, rarement chez l'adulte."},{"t":"Une orthèse d'avancée mandibulaire","ok":true,"why":"Elle est indiquée en première intention pour 15 ≤ IAH < 30 sans somnolence sévère ni comorbidité grave."},{"t":"Un traitement médicamenteux","ok":false,"why":"Aucun médicament n'est validé dans le traitement du SAHOS."}],"explanation":"L'OAM est indiquée, en l'absence de contre-indication dentaire et maxillo-faciale, en première intention pour 15 ≤ IAH < 30 sans somnolence sévère ni comorbidité grave, et en seconde intention en cas de refus ou d'intolérance à la PPC.","src":"p. 27-28"},{"id":"p110-qru-107","type":"QRU","rank":"B","objective":"p110-obj-16","tags":["diagnostic","paraclinique"],"difficulty":2,"stem":"Une femme de 60 ans, obèse, ronfle et se plaint d'une somnolence diurne ; son mari a constaté des pauses respiratoires nocturnes. Quel examen demander en première intention pour confirmer le diagnostic de SAHOS ?","options":[{"t":"Une polysomnographie systématique","ok":false,"why":"C'est l'examen de référence, proposé dans les situations complexes ou en deuxième intention."},{"t":"Le score d'Epworth seul","ok":false,"why":"Il quantifie la somnolence mais ne confirme pas le diagnostic."},{"t":"Une gazométrie artérielle systématique","ok":false,"why":"Elle est recommandée en cas de BPCO associée et d'obésité sévère (IMC > 35) et/ou de SpO2 d'éveil < 94 %."},{"t":"Une spirométrie seule","ok":false,"why":"Elle complète le bilan chez les fumeurs, obèses ou symptomatiques respiratoires mais ne confirme pas le SAHOS."},{"t":"Une polygraphie ventilatoire","ok":true,"why":"C'est l'examen de première intention en cas de suspicion de SAHOS."}],"explanation":"Un enregistrement respiratoire nocturne est nécessaire pour confirmer le diagnostic : la polygraphie ventilatoire est de première intention, la polysomnographie (référence) étant proposée dans les situations complexes ou en deuxième intention.","src":"p. 24-25"},{"id":"p110-qru-108","type":"QRU","rank":"A","objective":"p110-obj-14","tags":["diagnostic","étiologie"],"difficulty":2,"stem":"Selon le Collège, quel seuil de périmètre abdominal définit l'obésité abdominale chez la femme ?","options":[{"t":"Plus de 70 cm","ok":false,"why":"Seuil trop bas : le seuil est de 80 cm chez la femme."},{"t":"Plus de 94 cm","ok":false,"why":"C'est le seuil retenu chez l'homme."},{"t":"Plus de 100 cm","ok":false,"why":"Seuil trop élevé : le seuil est de 80 cm chez la femme."},{"t":"Plus de 80 cm","ok":true,"why":"Obésité abdominale si périmètre abdominal > 80 cm chez la femme (> 94 cm chez l'homme)."},{"t":"Plus de 110 cm","ok":false,"why":"Seuil trop élevé : le seuil est de 80 cm chez la femme."}],"explanation":"L'examen clinique calcule l'IMC (obésité si > 30 kg/m²) et mesure le périmètre abdominal (obésité abdominale si > 94 cm chez l'homme, > 80 cm chez la femme).","src":"p. 24"}],"edn":[],"trees":[],"treatments":{"data":[],"strategies":[]},"cases":[],"ecg":{"data":[],"method":""},"echo":{"data":[]},"flash":null,"pareto":{"id":"p110-pareto","points":[{"id":"p110-par-01","rank":"A","cat":"définition","text":"SAHOS = occlusions répétées des VAS pendant le sommeil ; défini par la clinique (**somnolence diurne excessive** ou ≥ 2 signes) + **IAH ≥ 5**/h","src":"p. 19-21"},{"id":"p110-par-02","rank":"A","cat":"définition","text":"Apnée = arrêt du flux ≥ **10 s** avec efforts ventilatoires (obstruction complète) ; hypopnée = baisse de ventilation > **30 %** ≥ 10 s + désaturation ≥ **3 %** et/ou micro-éveil","src":"p. 19-20"},{"id":"p110-par-03","rank":"A","cat":"gravité","text":"Sévérité par l'IAH : **légère 5-14**, **modérée 15-29**, **sévère ≥ 30**/h ; on tient compte aussi de la somnolence (conduite, travail) et des comorbidités CV/respiratoires","src":"p. 21"},{"id":"p110-par-04","rank":"A","cat":"clinique","text":"Signes évocateurs : **ronflements**, **pauses respiratoires** vues par l'entourage, **somnolence diurne**, nycturie, céphalées matinales, troubles de la libido","src":"p. 22"},{"id":"p110-par-05","rank":"A","cat":"étiologie","text":"Facteurs de risque : **obésité** (principal, IAH corrélé à l'IMC), **sexe masculin**, âge (femme : après la ménopause), anomalies des VAS (rétrognathie, macroglossie, amygdales)","src":"p. 21"},{"id":"p110-par-06","rank":"A","cat":"gravité","text":"Complications : **HTA**, diabète, coronaropathie, AVC, insuffisance cardiaque, troubles du rythme ; **accidents** de la route et du travail ; altération de la qualité de vie","src":"p. 21-22"},{"id":"p110-par-07","rank":"B","cat":"examen","text":"Confirmation = enregistrement nocturne : **polygraphie ventilatoire** en 1re intention, **polysomnographie** = référence (cas complexes ou échec de la polygraphie)","src":"p. 24-25"},{"id":"p110-par-08","rank":"B","cat":"traitement","text":"**PPC** = traitement le plus efficace : 1re intention si **IAH ≥ 30** ou 15-29 + somnolence sévère/comorbidités graves ; **OAM** si 15-29 sans gravité ou refus de la PPC","src":"p. 21, 26-28"},{"id":"p110-par-09","rank":"A","cat":"clinique","text":"Enfant : examen des **amygdales** systématique si ronflement rapporté, cassure de la pente de croissance ou troubles des acquisitions ; végétations → **occlusion nasale**","src":"p. 24"},{"id":"p110-par-10","rank":"A","cat":"définition","text":"Insomnie chronique : > **3 nuits/semaine** pendant > **3 mois** ; diagnostic clinique (agenda du sommeil 15 j), polygraphie jamais indiquée ; traitement **TCC**","src":"p. 23"},{"id":"p110-par-11","rank":"A","cat":"prévention","text":"Hygiène du sommeil : chambre calme, sans lumière, fraîche ; pas d'excitants après **14 h** ; pas de lumière directe **1 h** avant le coucher ; **écrans** hors de la chambre","src":"p. 26"},{"id":"p110-par-12","rank":"A","cat":"définition","text":"Sommeil normal : 3 stades (léger, profond, paradoxal), cycle **90-110 min**, **4-6 cycles**, sommeil paradoxal **20-25 %** ; 6-10 h/j (enfant : 16 h → 9 h)","src":"p. 19"},{"id":"p110-par-13","rank":"A","cat":"définition","text":"Autres troubles respiratoires du sommeil : **SAHCS** (commande ventilatoire centrale, ≈ **10 %** des SAS, bilan étiologique) ; **hypoventilation alvéolaire nocturne** (↑ CO2 + hypoxémie ; BPCO, obésité)","src":"p. 18-19"},{"id":"p110-par-14","rank":"B","cat":"examen","text":"**Epworth ≥ 11**/24 = somnolence excessive ; outil de **quantification**, pas de dépistage ; seulement **50 %** des patients SAHOS ont une somnolence excessive","src":"p. 22-23"},{"id":"p110-par-15","rank":"B","cat":"piège","text":"Hypersomnolence = **contre-indication à la conduite** ; arrêt de travail des conducteurs professionnels ; reprise après **1 mois** de traitement (clinique, ou EEG de maintien d'éveil pour poids lourd)","src":"p. 22"}]},"extra":{"semio":[],"criteres":[],"chiffres":[],"physio":[],"parcours":[],"examens":[]}});
